class Solution {
    public String lexSmallestAfterDeletion(String s) {
        int n = s.length();
        // suffixMask[i]: set of letters present in s[i..]; need: letters still missing
        int[] suffixMask = new int[n + 1];
        int need = 0;
        for (int i = n - 1; i >= 0; i--) {
            int bit = 1 << (s.charAt(i) - 'a');
            suffixMask[i] = suffixMask[i + 1] | bit;
            need |= bit;
        }

        // next[c][i]: first index >= i holding letter c, or -1
        int[][] next = new int[26][n + 1];
        for (int c = 0; c < 26; c++) next[c][n] = -1;
        for (int i = n - 1; i >= 0; i--) {
            for (int c = 0; c < 26; c++) next[c][i] = next[c][i + 1];
            next[s.charAt(i) - 'a'][i] = i;
        }

        StringBuilder sb = new StringBuilder();
        int start = 0;
        // stop once nothing is missing: a longer string would be bigger
        while (need != 0) {
            // smallest letter (repeats allowed) whose first occurrence keeps every other missing letter reachable
            for (int c = 0; c < 26; c++) {
                int pos = next[c][start];
                if (pos == -1) continue;
                int newNeed = need & ~(1 << c);
                if ((suffixMask[pos + 1] & newNeed) == newNeed) {
                    sb.append((char) ('a' + c));
                    need = newNeed;
                    start = pos + 1;
                    break;
                }
            }
        }
        return sb.toString();
    }
}

