var lexSmallestAfterDeletion = function(s) {
    const n = s.length;
    const aCharCode = 'a'.charCodeAt(0);

    // suffix_mask[i] = bitmask of letters in s[i:]
    const suffix_mask = new Array(n + 1).fill(0);
    for (let i = n - 1; i >= 0; i--) {
        suffix_mask[i] = suffix_mask[i + 1] | (1 << (s.charCodeAt(i) - aCharCode));
    }

    // positions of each letter, with a pointer per letter
    const pos = Array.from({ length: 26 }, () => []);
    for (let i = 0; i < n; i++) {
        pos[s.charCodeAt(i) - aCharCode].push(i);
    }
    const ptr = new Array(26).fill(0);

    // R_mask: letters still missing from the result (all distinct letters at first)
    let R_mask = 0;
    for (let i = 0; i < n; i++) {
        R_mask |= (1 << (s.charCodeAt(i) - aCharCode));
    }

    let start = 0;
    const result = [];

    // stop once nothing is missing: a longer string would be bigger
    while (R_mask !== 0) {
        for (let c = 0; c < 26; c++) {
            // advance pointer to first occurrence >= start
            while (ptr[c] < pos[c].length && pos[c][ptr[c]] < start) {
                ptr[c]++;
            }
            if (ptr[c] < pos[c].length) {
                const i = pos[c][ptr[c]];
                // feasible iff every other missing letter still occurs after i
                const required = R_mask & ~(1 << c);
                if ((suffix_mask[i + 1] & required) === required) {
                    result.push(String.fromCharCode(c + aCharCode));
                    start = i + 1;
                    R_mask &= ~(1 << c); // remove c from required if present
                    break;
                }
            }
        }
    }

    return result.join('');
};

