func lexSmallestAfterDeletion(s string) string {
    n := len(s)
    if n == 0 {
        return ""
    }

    // suffixMask[i]: set of letters present in s[i:]
    suffixMask := make([]int, n+1)
    for i := n - 1; i >= 0; i-- {
        suffixMask[i] = suffixMask[i+1] | (1 << (s[i] - 'a'))
    }

    // next[i][c]: first index >= i holding letter c, or -1
    next := make([][26]int, n+1)
    for c := 0; c < 26; c++ {
        next[n][c] = -1
    }
    for i := n - 1; i >= 0; i-- {
        for c := 0; c < 26; c++ {
            next[i][c] = next[i+1][c]
        }
        next[i][s[i]-'a'] = i
    }

    // need: letters still missing; stop once it is empty (a longer string would be bigger)
    need := suffixMask[0]
    pos := 0
    res := make([]byte, 0, n)

    for need != 0 {
        // smallest letter (repeats allowed) whose first occurrence keeps every missing letter reachable
        for c := 0; c < 26; c++ {
            j := next[pos][c]
            if j == -1 {
                continue
            }
            union := suffixMask[j+1] | (1 << c)
            if (union & need) == need {
                res = append(res, byte('a'+c))
                pos = j + 1
                need &^= (1 << c)
                break
            }
        }
    }

    return string(res)
}
